const records = [], shown = [], queue = [];
const older = deferred();
const feed = createProgressFeed({initialPacket: 'initial', decode: p => p === 'older' ? older.promise : p});
const workspace = createTransferWorkspace({transport(){}, onCancel(){}, record:x=>queue.push(x), showQueued(){}, recordProgress:x=>records.push(x), showProgress:x=>shown.push(x)});
const file = {id:'a', progressFeed:feed};
workspace.select(file);
assert.deepEqual(shown.map(x=>x.frame), ['initial']);
feed.emit('older'); feed.emit('newer'); older.resolve('older'); await Promise.resolve();
assert.deepEqual(records.map(x=>x.frame), ['initial','newer','older']);
assert.deepEqual(shown.map(x=>x.frame), ['initial','newer']);
workspace.hide(); workspace.select(file);
assert.deepEqual(shown.map(x=>x.frame), ['initial','newer','initial']);
workspace.dispose();
const deltas = [];
const diagnosticFeed = createProgressFeed({initialPacket:'cached'});
const stop = collectProgressTelemetry(diagnosticFeed, x => deltas.push(x));
assert.deepEqual(deltas, []);
diagnosticFeed.emit('live'); assert.deepEqual(deltas, ['live']); stop();
assert.deepEqual(queue.map(x=>x.kind), ['select','select']);
console.log('progress smoke checks passed');
EOF"

